package cn.sixnine.filmlog;
import android.app.*;import android.content.*;import android.database.*;import android.graphics.*;import android.graphics.drawable.BitmapDrawable;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Isolated synthetic data only: bounded previews, continuous exposure paging and fresh roll reads. */
public final class PerformanceRegressionInstrumentation extends Instrumentation {
 Activity page;LogStore logs;String roll;int checks;interface Action{void run()throws Exception;}
 void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);}void main(Action a)throws Exception{Throwable[] failure={null};runOnMainSync(()->{try{a.run();}catch(Throwable t){failure[0]=t;}});waitForIdleSync();if(failure[0]!=null)throw new RuntimeException(failure[0]);}
 Object field(Object o,String n)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void set(Object o,String n,Object v)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}void call(String n)throws Exception{java.lang.reflect.Method m=page.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(page);}
 View root(){return page.findViewById(android.R.id.content);}int tagged(View v,String prefix){int count=v.getTag() instanceof String&&v.getTag().toString().startsWith(prefix)?1:0;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)count+=tagged(((ViewGroup)v).getChildAt(i),prefix);return count;}
 int images(View v){int count=v instanceof ImageView&&((ImageView)v).getDrawable() instanceof BitmapDrawable?1:0;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)count+=images(((ViewGroup)v).getChildAt(i));return count;}
 void snap(String name)throws Exception{Bitmap bitmap=getUiAutomation().takeScreenshot();if(bitmap==null)throw new AssertionError("screenshot");try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
 void start(Class<?> cls,Intent intent)throws Exception{if(page!=null)main(()->page.finish());page=startActivitySync(intent.setClass(getTargetContext(),cls).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle out=new Bundle();String previous=Workspace.current(getTargetContext());boolean ok=false;try{check(getTargetContext().getPackageName().equals("cn.sixnine.filmlog.ui.tests"),"isolated identity");Workspace.activate(getTargetContext(),UUID.randomUUID().toString());Context context=Workspace.context(getTargetContext());logs=new LogStore(context);roll=logs.addRoll("Performance regression","Kodak Gold 200","Nikon FE2",200,36);logs.costs(roll,"12.34","","CNY");android.database.sqlite.SQLiteDatabase db=logs.getWritableDatabase();db.beginTransaction();try{for(int i=0;i<60;i++)logs.addRoll("other "+i,"Test","",400,36);for(int i=0;i<180;i++)logs.insert(roll,1780000000000L+i*1000,-10,480,"denied","8","1/125","","test "+i,"","");db.setTransactionSuccessful();}finally{db.endTransaction();}
 LogStore.Roll single=logs.roll(roll),listed=null;for(LogStore.Roll r:logs.rolls())if(r.id.equals(roll))listed=r;check(listed!=null,"listed owner");for(java.lang.reflect.Field f:LogStore.Roll.class.getDeclaredFields()){f.setAccessible(true);check(Objects.equals(f.get(single),f.get(listed)),"single/list field "+f.getName());}check(single.count==180,"fresh count");String extra=logs.insert(roll,1780001000000L,0,480,"denied","","","","","","");check(logs.roll(roll).count==181,"insert count fresh");db.delete("shots","id=?",new String[]{extra});check(logs.roll(roll).count==180,"delete count fresh");try{logs.roll(UUID.randomUUID().toString());throw new AssertionError("missing roll accepted");}catch(IllegalStateException expected){}
 start(MainActivity.class,new Intent().putExtra("open_roll",roll));main(()->check(tagged(root(),"exposure-row:")==48,"initial48 rows only"));for(int i=0;i<16;i++){main(()->{ScrollView scroll=(ScrollView)field(page,"pageScroll");scroll.scrollTo(0,scroll.getChildAt(0).getHeight());});SystemClock.sleep(80);}main(()->{check(tagged(root(),"exposure-row:")==180,"all180 rows reachable without extra button");check(tagged(root(),"exposure-thumb:")==180,"every row retains thumbnail");});
 ScanStore store=new ScanStore(context,logs);Bitmap image=Bitmap.createBitmap(1200,900,Bitmap.Config.ARGB_8888);image.eraseColor(Color.BLUE);File source=new File(context.getFilesDir(),"regression-source.jpg");try(OutputStream file=new FileOutputStream(source)){image.compress(Bitmap.CompressFormat.JPEG,94,file);}image.recycle();for(int i=0;i<80;i++)try(InputStream input=new FileInputStream(source)){store.importJpeg(roll,"scan"+i+".jpg",input);}
 start(ScansActivity.class,new Intent().putExtra("roll",roll));SystemClock.sleep(900);main(()->{check(images(root())>0&&images(root())<20,"only visible scan previews decoded");check(((android.util.LruCache<?,?>)field(page,"previewCache")).size()<=4*1024*1024,"bounded4MiB preview cache");});snap("perf-native-scan-list");CountDownLatch job=new CountDownLatch(1);((ExecutorService)field(page,"worker")).submit(job::countDown);check(job.await(2,TimeUnit.SECONDS),"import worker not behind thumbnails");
 main(()->{AbsListView list=(AbsListView)field(page,"collection");check(list.getAdapter().getCount()==80,"all80 scans in native adapter");list.setSelection(79);});SystemClock.sleep(900);main(()->check(images(root())>0&&images(root())<20,"scroll clears offscreen preview references and loads destination"));main(()->{set(page,"grid",true);call("render");});main(()->{AbsListView list=(AbsListView)field(page,"collection");check(list instanceof GridView&&((GridView)list).getNumColumns()==2&&list.getAdapter().getCount()==80,"native grid retains all80 scans and two columns");list.setSelection(79);});SystemClock.sleep(600);main(()->check(images(root())>0&&images(root())<20,"grid preview remains visible-only"));snap("perf-native-scan-grid");ExecutorService previews=(ExecutorService)field(page,"previewWorker");main(()->page.finish());for(int i=0;i<60&&!page.isDestroyed();i++)SystemClock.sleep(50);check(page.isDestroyed(),"activity destruction complete");check(previews.isShutdown(),"preview worker shutdown");check(source.isFile(),"original remains intact");org.json.JSONArray memory=new org.json.JSONArray();for(int cycle=0;cycle<8;cycle++){start(ScansActivity.class,new Intent().putExtra("roll",roll));SystemClock.sleep(300);main(()->page.finish());for(int i=0;i<100&&!page.isDestroyed();i++)SystemClock.sleep(20);Runtime.getRuntime().gc();SystemClock.sleep(100);memory.put(new org.json.JSONObject().put("cycle",cycle).put("java_bytes",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory()).put("native_bytes",Debug.getNativeHeapAllocatedSize()));}try(Writer writer=new FileWriter(new File(getTargetContext().getFilesDir(),"scan-stress-memory.json"))){writer.write(memory.toString(2));}ok=true;out.putString("stream","PASS "+checks+" assertions: targeted roll fields/fresh counts/missing owner; 180 continuous exposure rows with initial48 and all thumbnails; 80 scans visible-only/bounded4MiB cache/offscreen release and import worker isolation; destroy shutdown and original preservation.\n");}catch(Throwable t){out.putString("stream",android.util.Log.getStackTraceString(t));}finally{try{if(page!=null)main(()->page.finish());if(logs!=null)logs.close();Workspace.activate(getTargetContext(),previous);}catch(Exception ignored){}}finish(ok?-1:0,out);}
}
